#include "shell/thumbnail_cache.hpp"
#include <algorithm>
#include <fstream>
#include <stdexcept>
namespace squiflow::shell{bool ThumbnailCache::valid(const ThumbnailKey&k)noexcept{return !k.file_id.empty()&&k.file_id.size()<=128&&k.file_id.find('/')==k.file_id.npos&&k.file_id.find('\\')==k.file_id.npos&&k.content_hash.size()==64&&std::all_of(k.content_hash.begin(),k.content_hash.end(),[](char c){return(c>='0'&&c<='9')||(c>='a'&&c<='f');});}ThumbnailCache::ThumbnailCache(std::filesystem::path r,std::uint64_t c,std::size_t e):root_(std::move(r)),cap_(c),entry_cap_(e){if(root_.empty()||!c||!e)throw std::invalid_argument("invalid cache");std::filesystem::create_directories(root_);}void ThumbnailCache::evict(){while(entries_.size()>entry_cap_||bytes_>cap_){auto i=std::min_element(entries_.begin(),entries_.end(),[](auto&a,auto&b){return a.access<b.access;});std::error_code x;std::filesystem::remove(i->path,x);bytes_-=i->bytes;entries_.erase(i);}}app::Result<std::filesystem::path,ThumbnailError> ThumbnailCache::store(const ThumbnailKey&k,std::span<const std::uint8_t>b){if(!valid(k)||b.empty()||b.size()>cap_)return app::Result<std::filesystem::path,ThumbnailError>::failure({"image.error.invalid_or_large"});std::scoped_lock l(mutex_);for(auto i=entries_.begin();i!=entries_.end();)if(i->key.file_id==k.file_id){std::error_code x;std::filesystem::remove(i->path,x);bytes_-=i->bytes;i=entries_.erase(i);}else++i;auto p=root_/(k.content_hash+"-"+std::to_string(std::hash<std::string>{}(k.file_id))+".png");auto tmp=p;tmp+=".tmp";std::ofstream o(tmp,std::ios::binary);o.write(reinterpret_cast<const char*>(b.data()),static_cast<std::streamsize>(b.size()));o.close();std::error_code x;std::filesystem::rename(tmp,p,x);if(x)return app::Result<std::filesystem::path,ThumbnailError>::failure({"image.error.cache_write"});entries_.push_back({k,p,static_cast<std::uint64_t>(b.size()),++clock_});bytes_+=b.size();evict();auto f=std::find_if(entries_.begin(),entries_.end(),[&](auto&e){return e.key==k;});return f==entries_.end()?app::Result<std::filesystem::path,ThumbnailError>::failure({"image.error.evicted"}):app::Result<std::filesystem::path,ThumbnailError>::success(p);}std::optional<std::filesystem::path> ThumbnailCache::lookup(const ThumbnailKey&k){std::scoped_lock l(mutex_);auto i=std::find_if(entries_.begin(),entries_.end(),[&](auto&e){return e.key==k;});if(i==entries_.end())return{};i->access=++clock_;return i->path;}std::size_t ThumbnailCache::entry_count()const{std::scoped_lock l(mutex_);return entries_.size();}std::uint64_t ThumbnailCache::byte_count()const{std::scoped_lock l(mutex_);return bytes_;}}
